    /// <summary>
    /// Bilinearly interpolates the exact North Island terrain elevation at world (x, z).
    /// </summary>
    internal static float SampleHeight(float x, float z)
    {
        float fx = System.Math.Clamp((x - MinX) / Step, 0f, CountX - 1.0001f);
        float fz = System.Math.Clamp((z - MinZ) / Step, 0f, CountZ - 1.0001f);

        int ix = (int)fx;
        int iz = (int)fz;
        float tx = fx - ix;
        float tz = fz - iz;

        float h00 = Heights[iz * CountX + ix];
        float h10 = Heights[iz * CountX + (ix + 1)];
        float h01 = Heights[(iz + 1) * CountX + ix];
        float h11 = Heights[(iz + 1) * CountX + (ix + 1)];

        float h0 = h00 + (h10 - h00) * tx;
        float h1 = h01 + (h11 - h01) * tx;
        return h0 + (h1 - h0) * tz;
    }
